formulas.expression:
IF(
    ISBLANK({!varProductoId}),
    "Todos los productos de la factura",
    {!varProductoId}
)

IF(

  {!seleccionPortipoUM} = "KG",

  /* Cálculo cuando el usuario selecciona KG */
  IF(
    {!ProductosDeLaFactura_1.outputSelectedRow.Peso_neto__c} > 0,
    ROUND(
      {!Cantidad_Reclamada} *
      (
        {!ProductosDeLaFactura_1.outputSelectedRow.Total_con_Rapel__c} /
        {!ProductosDeLaFactura_1.outputSelectedRow.Peso_neto__c}
      ),
      0
    ),
    0
  ),

  /* Cálculo cuando el usuario selecciona Caja */
  IF(
    {!ProductosDeLaFactura_1.outputSelectedRow.Cantidad__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_1} *
      (
        {!ProductosDeLaFactura_1.outputSelectedRow.Total_con_Rapel__c} /
        {!ProductosDeLaFactura_1.outputSelectedRow.Cantidad__c}
      ),
      0
    ),
    0
  )

)

IF(
  {!productosFacturaSucursal.outputSelectedRow.Unidad_de_Medida__c} = "KG",

  /* Cálculo cuando es KG */
  IF(
    {!productosFacturaSucursal.outputSelectedRow.Peso_neto__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_sucursal} *
      (
        {!productosFacturaSucursal.outputSelectedRow.Total_con_Rapel__c} /
        {!productosFacturaSucursal.outputSelectedRow.Peso_neto__c}
      ),
      0
    ),
    0
  ),

  /* Cálculo cuando NO es KG */
  IF(
    {!productosFacturaSucursal.outputSelectedRow.Cantidad__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_1_sucursal} *
      (
        {!productosFacturaSucursal.outputSelectedRow.Total_con_Rapel__c} /
        {!productosFacturaSucursal.outputSelectedRow.Cantidad__c}
      ),
      0
    ),
    0
  )
)
